mapper.select:
select t.region_code as code, t.region_level as level, t.region_name as areaName, (select longitude from sys_area where area_code = t.region_code ) as longitude, (select latitude from sys_area where area_code = t.region_code ) as latitude, IFNULL(( SELECT sum(dataTable.today_all ) FROM (select t.province_id as province_code, t.city_id as city_code,t.* from vm_statistics_event_num_day_tt t) dataTable WHERE dataTable.province_code = t.region_code
AND dataTable.create_date >= DATE_FORMAT(#{param.webStartDate}, '%Y-%m-%d' ) AND dataTable.create_date <= DATE_FORMAT(#{param.webEndDate}, '%Y-%m-%d %H:%i:%s' )
${param.dataScope} ),0) as alarmNum, IFNULL(( SELECT sum(device_num ) FROM vm_statistics_devices_tt WHERE province_id = t.region_code ),0) as deviceNum, ( SELECT count(keeper_id) FROM bm_gridkeeper WHERE province_id = t.region_code and TIMESTAMPDIFF(MINUTE,attribute10,now())<5
and tenant_id = #{param.tenantId}
)as gridkeeperNum from vm_area_t t where t.region_level = '1'
and t.region_code in
#{item}
group by t.region_code having deviceNum != 0

SELECT region_code FROM vm_area_t WHERE delete_flag = '0'
and parent_code in
#{item}

select t.region_code as code, t.region_level as level, t.region_name as areaName, (select longitude from sys_area where area_code = t.region_code ) as longitude, (select latitude from sys_area where area_code = t.region_code ) as latitude, IFNULL(( SELECT sum(dataTable.today_all ) FROM (select t.province_id as province_code, t.city_id as city_code,t.* from vm_statistics_event_num_day_tt t) dataTable WHERE dataTable.city_code = t.region_code
AND dataTable.create_date >= DATE_FORMAT(#{param.webStartDate}, '%Y-%m-%d' ) AND dataTable.create_date <= DATE_FORMAT(#{param.webEndDate}, '%Y-%m-%d %H:%i:%s' )
${param.dataScope} ),0) as alarmNum, IFNULL(( SELECT sum(device_num) FROM vm_statistics_devices_tt WHERE city_id = t.region_code ),0) as deviceNum, ( SELECT count(keeper_id) FROM bm_gridkeeper WHERE city_id = t.region_code and (case when TIMESTAMPDIFF(MINUTE,attribute10,now()) <5 then '1' else '0' end) ='1'
and tenant_id = #{param.tenantId}
)as gridkeeperNum from vm_area_t t where t.region_level = '2'
and t.region_code in
#{item}
group by t.region_code having deviceNum != 0
